package com.bank.statement.service;

import com.bank.statement.model.PageNode;
import java.util.logging.Logger;

// Reorders pages into first-last-second-secondlast order, in place.
public class StatementReorderer {
    private static final Logger log = Logger.getLogger(StatementReorderer.class.getName());

    public void reorder(PageNode head) {
        if (head == null || head.next == null) return;

        // 1. Find the middle.
        PageNode slow = head, fast = head;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        // 2. Reverse the second half and cut the link cleanly.
        PageNode secondHead = reverse(slow.next);
        slow.next = null; // break the two halves apart to avoid a cycle

        // 3. Merge the two halves alternately.
        PageNode first = head, second = secondHead;
        while (second != null) {
            PageNode firstNext = first.next;
            PageNode secondNext = second.next;
            first.next = second;      // first → second
            second.next = firstNext;  // second → old first.next
            first = firstNext;
            second = secondNext;
        }
        log.info("Statement pages reordered (interleaved from both ends).");
    }

    private PageNode reverse(PageNode node) {
        PageNode prev = null;
        while (node != null) {
            PageNode next = node.next;
            node.next = prev;
            prev = node;
            node = next;
        }
        return prev;
    }
}
