package com.bank.statement;

import com.bank.statement.model.PageNode;
import com.bank.statement.service.StatementReorderer;
import java.util.logging.Logger;

public class ReorderDemo {
    private static final Logger log = Logger.getLogger(ReorderDemo.class.getName());

    public static void main(String[] args) {
        PageNode head = chain(new String[]{"P1", "P2", "P3", "P4"});

        StatementReorderer reorderer = new StatementReorderer();
        reorderer.reorder(head);

        log.info(() -> "New order: " + toText(head));
    }

    private static PageNode chain(String[] ids) {
        PageNode dummy = new PageNode("D");
        PageNode tail = dummy;
        for (String id : ids) { tail.next = new PageNode(id); tail = tail.next; }
        return dummy.next;
    }

    private static String toText(PageNode head) {
        StringBuilder sb = new StringBuilder("[");
        for (PageNode n = head; n != null; n = n.next) {
            sb.append(n.pageId);
            if (n.next != null) sb.append(" -> ");
        }
        return sb.append("]").toString();
    }
}
